select

from flow_current_node t
where t.del_flag = '0'
     and t.id = #{id}
     and t.FLOW_OID = #{flowOid}
     and t.CURRENT_OID = #{currentOid}
     and t.NODE_ORDER = #{nodeOrder}
     and t.NODE_KEY = #{nodeKey}
     and t.NODE_NAME like concat('%', #{nodeName}, '%')
     and t.CONFIG_TYPE = #{configType}
     and t.CONFIG_ID = #{configId}
     and t.CONFIG_NAME like concat('%', #{configName}, '%')
     and t.BILL_OID = #{billOid}
     and t.AUIT_EMP_OID = #{auitEmpOid}
     and t.AUIT_EMP_NAME like concat('%', #{auitEmpName}, '%')
     and t.BACK_COL1 = #{backCol1}
     and t.BACK_COL2 = #{backCol2}
     and t.BACK_COL3 = #{backCol3}
     and t.sort = #{sort}
     and t.eps_id = #{epsId}
     and t.create_by = #{createBy}
  order by t.create_time desc,t.id

select

from flow_current_node t
where t.ID = #{id}

