FLOW_OID = #{flowOid}, CURRENT_OID = #{currentOid}, NODE_ORDER = #{nodeOrder}, NODE_KEY = #{nodeKey}, NODE_NAME = #{nodeName}, CONFIG_TYPE = #{configType}, CONFIG_ID = #{configId}, CONFIG_NAME = #{configName}, BILL_OID = #{billOid}, AUIT_EMP_OID = #{auitEmpOid}, AUIT_EMP_NAME = #{auitEmpName}, BACK_COL1 = #{backCol1}, BACK_COL2 = #{backCol2}, BACK_COL3 = #{backCol3}, sort = #{sort}, eps_id = #{epsId}, del_flag = #{delFlag}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime},
